CUDA = DEVICE.type == "cuda"

def gpu_mib(kind="alloc"):
    # Current or peak allocated GPU memory in MiB (0 on CPU).
    if not CUDA:
        return 0.0
    fn = {"alloc": torch.cuda.memory_allocated,
          "peak": torch.cuda.max_memory_allocated,
          "reserved": torch.cuda.memory_reserved}[kind]
    return fn() / 2**20

def reset_peak():
    if CUDA:
        torch.cuda.reset_peak_memory_stats()

def sync():
    if CUDA:
        torch.cuda.synchronize()

print(f"model resident: {gpu_mib():.1f} MiB")

def cache_bytes(cache):
    total = 0
    for key in cache.keys():
        value = cache[key].output
        for tensor in (value if isinstance(value, (tuple, list)) else [value]):
            if isinstance(tensor, torch.Tensor):
                total += tensor.numel() * tensor.element_size()
    return total

def time_cache(modules):
    times = []
    for _ in range(3):
        sync(); t0 = time.time()
        with torch.no_grad():
            with model.trace({"input_ids": ids}) as tracer:
                c = (tracer.cache(dtype=torch.float16) if modules is None
                     else tracer.cache(modules=modules, dtype=torch.float16))
        sync(); times.append(time.time() - t0)
    return min(times), len(list(c.keys())), cache_bytes(c)

for label, mods in [("cache()            ", None), ("cache(modules=[...])", MODULES)]:
    dt, n_mod, nbytes = time_cache(mods)
    print(f"{label}  {dt*1000:7.1f} ms/batch   {n_mod:3d} modules   "
