def collect(out_dir, crash_at=None):
    os.makedirs(out_dir, exist_ok=True)
    done = completed_shards(out_dir)
    print(f"[resume] {len(done)} of {N_SEQ // SHARD_SEQ} shards already complete")

    log, tokens, t0 = [], 0, time.time()
    for s in range(N_SEQ // SHARD_SEQ):
        if s in done:
            continue
        if crash_at is not None and s == crash_at:
            raise RuntimeError(f"simulated crash at shard {s}")

        rows = np.arange(s * SHARD_SEQ, (s + 1) * SHARD_SEQ)
        parts = {name: [] for name in NAMES}
        for b in range(0, SHARD_SEQ, BATCH):
            batch_ids = torch.from_numpy(corpus[rows[b:b + BATCH]].astype(np.int64))
            captured = capture_batch(batch_ids)
            for name in NAMES:
                parts[name].append(captured[name])
            del captured                                  # free the batch before the next one

        payload = {"acts": {name: torch.cat(parts[name]) for name in NAMES},
                   "tokens": torch.from_numpy(corpus[rows].astype(np.int32)),
                   "rows": torch.from_numpy(rows)}
        del parts

        write_shard(out_dir, s, payload, rows)
        del payload

        tokens += SHARD_SEQ * SEQ_LEN
        log.append({"shard": s, "allocated": gpu_mib("alloc"), "peak": gpu_mib("peak"),
                    "reserved": gpu_mib("reserved"), "elapsed": time.time() - t0,
                    "tokens": tokens})
    return log, tokens / max(time.time() - t0, 1e-9)

reset_peak()
