from collections import defaultdict

def matched_pairs(seq_ids, seed=0):
    # Keep equal numbers of repeat/non-repeat examples within every (position, token id).
    rng = np.random.default_rng(seed)
    groups = defaultdict(lambda: ([], []))
    for i in seq_ids:
        for t in range(SEQ_LEN):
            groups[(t, tokens[i, t])][int(repeat[i, t])].append((i, t))
    examples = []
    for negatives, positives in groups.values():
        k = min(len(negatives), len(positives))
        if k == 0:
            continue
        for j in rng.permutation(len(positives))[:k]:
            examples.append((*positives[j], 1))
        for j in rng.permutation(len(negatives))[:k]:
            examples.append((*negatives[j], 0))
    return np.array(examples, dtype=np.int64)

# split by SEQUENCE first, then match within each split -- no window leaks across the split
train_ex = matched_pairs(np.arange(0, 1536))
test_ex = matched_pairs(np.arange(1536, N_SEQ))
y_train, y_test = train_ex[:, 2], test_ex[:, 2]

print(f"train {len(train_ex):6,} examples, positive rate {y_train.mean():.4f}")
print(f"test  {len(test_ex):6,} examples, positive rate {y_test.mean():.4f}")
print(f"distinct token ids in the matched set: "
